<?= $this->extend('layouts/main') ?>
<?= $this->section('content') ?>
<?php
$organization = $organization ?? [];
$stats = $stats ?? ['branches' => 0, 'staff' => 0, 'visitors' => 0, 'active_visits' => 0];
$recentChanges = $recentChanges ?? [];
$status = $organization['status'] ?? 'active';
$statusMap = ['active' => ['class' => 'badge-success', 'label' => 'Active', 'tone' => 'green'], 'inactive' => ['class' => 'badge-neutral', 'label' => 'Inactive', 'tone' => 'gray'], 'suspended' => ['class' => 'badge-danger', 'label' => 'Suspended', 'tone' => 'red']];
$currentStatus = $statusMap[$status] ?? $statusMap['inactive'];
?>
<div class="breadcrumb"><a href="<?= site_url('organizations') ?>">Organizations</a><span class="breadcrumb__sep">/</span><a href="<?= site_url('organizations/' . (int) $organization['id']) ?>"><?= esc($organization['name'] ?? 'Organization') ?></a><span class="breadcrumb__sep">/</span><span>Lifecycle</span></div>
<div class="lifecycle-heading"><div><span class="eyebrow">Organization administration</span><h1><?= esc($organization['name'] ?? 'Organization') ?></h1><p>Control tenant access and review its operational lifecycle.</p></div><span class="badge <?= $currentStatus['class'] ?>"><span class="badge__dot"></span><?= esc($currentStatus['label']) ?></span></div>
<div class="lifecycle-layout">
  <div class="lifecycle-main">
    <section class="lifecycle-panel"><div class="lifecycle-panel__header"><div><h2>Current status</h2><p>The status controls whether this organization and its staff can access the platform.</p></div><span class="status-orb status-orb--<?= esc($currentStatus['tone']) ?>"></span></div><div class="lifecycle-current"><div><span class="lifecycle-current__label">Current lifecycle state</span><strong><?= esc($currentStatus['label']) ?></strong><small>Last updated <?= !empty($organization['updated_at']) ? esc(date('d M Y, H:i', strtotime($organization['updated_at']))) : 'Not available' ?></small></div><a href="<?= site_url('organizations/' . (int) $organization['id']) ?>" class="btn btn-secondary btn-sm">View organization</a></div></section>
    <section class="lifecycle-panel"><div class="lifecycle-panel__header"><div><h2>Change organization status</h2><p>Choose the state that best reflects this tenant's access.</p></div></div><div class="status-options">
      <?php foreach (['active' => ['green', 'Active', 'Organization and staff can use the platform normally.', 'Available'], 'inactive' => ['gray', 'Inactive', 'Temporarily pause access without removing organization data.', 'Paused'], 'suspended' => ['red', 'Suspended', 'Restrict access because of a compliance or operational concern.', 'Restricted']] as $value => [$tone, $label, $description, $availability]): ?><label class="status-option status-option--<?= $tone ?> <?= $status === $value ? 'is-current' : '' ?>"><input type="radio" name="status_preview" value="<?= $value ?>" <?= $status === $value ? 'checked' : '' ?>><span><strong><?= $label ?></strong><small><?= $description ?></small></span><b><?= $availability ?></b></label><?php endforeach; ?>
    </div><div class="lifecycle-submit"><form method="post" action="<?= site_url('organizations/' . (int) $organization['id'] . '/status') ?>" data-lifecycle-form><?= csrf_field() ?><input type="hidden" name="status" value="<?= esc($status) ?>" data-status-value><button type="submit" class="btn btn-primary" data-status-submit <?= $status === 'active' ? 'disabled' : '' ?>>Save status change</button></form></div></section>
    <section class="lifecycle-panel"><div class="lifecycle-panel__header"><div><h2>Lifecycle history</h2><p>Status changes and organization updates recorded in the audit trail.</p></div><a href="<?= site_url('audit-log') ?>" class="btn btn-secondary btn-sm">Full audit log</a></div><div class="lifecycle-history"><?php if (!$recentChanges): ?><div class="empty-state"><h3>No lifecycle history</h3><p>Organization changes will appear here as they are recorded.</p></div><?php else: foreach ($recentChanges as $change): ?><div class="history-row"><span class="history-row__marker"></span><div><strong><?= esc($change['description'] ?? 'Organization updated') ?></strong><small><?= !empty($change['created_at']) ? esc(date('d M Y, H:i', strtotime($change['created_at']))) : '—' ?></small></div><span class="badge badge-neutral"><?= esc(ucwords(str_replace('_', ' ', $change['action'] ?? 'update'))) ?></span></div><?php endforeach; endif; ?></div></section>
  </div>
  <aside class="lifecycle-aside"><div class="card lifecycle-impact"><span class="eyebrow">Tenant footprint</span><h2>Organization at a glance</h2><div class="impact-grid"><div><strong><?= (int) $stats['branches'] ?></strong><span>Locations</span></div><div><strong><?= (int) $stats['staff'] ?></strong><span>Staff accounts</span></div><div><strong><?= (int) $stats['visitors'] ?></strong><span>Visitors</span></div><div><strong class="<?= $stats['active_visits'] ? 'impact-warning' : '' ?>"><?= (int) $stats['active_visits'] ?></strong><span>Currently on site</span></div></div></div><div class="lifecycle-warning"><strong>Before changing access</strong><p>Changing an organization to inactive or suspended blocks staff sign-in. Active visits must be checked out first.</p></div></aside>
</div>
<?= $this->endSection() ?>
