<?= $this->section('scripts') ?><script>
document.querySelectorAll('input[name="status_preview"]').forEach(function(input){input.addEventListener('change',function(){document.querySelector('[data-status-value]').value=this.value;document.querySelector('[data-status-submit]').disabled=this.value==='<?= esc($status) ?>';});});
document.querySelector('[data-lifecycle-form]')?.addEventListener('submit',function(event){var status=document.querySelector('[data-status-value]').value;if(status!=='<?= esc($status) ?>'&&!window.confirm('Change this organization status to '+status+'?')){event.preventDefault();}});
</script><?= $this->endSection() ?>
